components.calculateValue:
let checkMainContact = false;
const contacts = _.get(data, 'contacts', []);

for (const contact of contacts) {
  if (contact.contactMain) {
    checkMainContact = true;
    break;
  }
}

if (checkMainContact && contacts.length && !contacts[0].contactMain) {
  const sortedContacts = contacts;
  sortedContacts.sort((a, b) => b.contactMain - a.contactMain);
  var dataGridInst = util.searchComponents(instance.parent.components, "contacts");
  dataGridInst[0].setValue(sortedContacts);
}

// A contact list that was rendered once keeps a blank row in the data, so its length says
// nothing about whether the record has contacts - look at what the rows contain. The value is
// what the "there are no contacts" text and the list itself are shown by.
const hasOwnContacts = contacts.some((contact) => {
  return !!contact && (!!contact.contactFio || !!contact.contactPosition ||
    !!contact.contactDepartment || !!contact.contactPhone ||
    !!contact.contactEmail || !!contact.contactComment);
});

value = hasOwnContacts;

// The dialog and the dashlet render separate form instances, so the cards are looked up inside
// the one running this script.
const isViewMode = !!_.get(instance, 'root.options.viewAsHtml');
// Scope the lookup to this form - the dialog and the dashlet are separate instances. A form
// that has been replaced keeps its markup in a detached tree, and working on that tree changes
// nothing the user sees, so such an instance falls back to the live document.
const rootElement = _.get(instance, 'root.element');
const formRoot = (rootElement && document.contains(rootElement)) ? rootElement : document;

// Deferred by a tick: the conditions that decide which lists are shown are applied after this
// script runs, so looking at the markup right away finds the lists still hidden.
setTimeout(function () {
const contactGrids = formRoot.querySelectorAll('.citeck-widget-contacts .formio-component-datagrid');
for (let g = 0; g < contactGrids.length; g++) {
  const grid = contactGrids[g];

  if (grid.hasAttribute('hidden') || grid.closest('[hidden]')) {
    continue;
  }

  const cards = grid.querySelectorAll('.citeck-widget-contacts__not-collapsed');
  for (let i = 0; i < cards.length; i++) {
    const card = cards[i];

    if (card.closest('[hidden]')) {
      continue;
    }

    // An empty contact list still renders one blank row. While reading the record that row is
    // a column of dashes, so it stays shut; in the dialog it is the form for the first contact
    // and has to be open.
    const cardTitle = card.querySelector('.card-title');
    if (isViewMode && (!cardTitle || !cardTitle.textContent.trim())) {
      continue;
    }

    const cardBody = card.querySelector('.panel-body');
    if (!cardBody) {
      continue;
    }

    cardBody.removeAttribute('hidden');
    cardBody.removeAttribute('style');

    const iconElement = card.querySelector('.citeck-panel-icon-chevron');
    if (iconElement) {
      iconElement.className = "citeck-panel-icon-chevron down";
    }

    break;
  }
}
}, 0);

